	@Test
	void recursiveLeastSquaresLearnsStartupAndStaysNonNegative() {
		double[] prior = new double[LmdbNativeCostVector.Feature.values().length];
		for (int i = 0; i < prior.length; i++) {
			prior[i] = 10_000.0;
		}
		LmdbNativeMachineCostModel model = new LmdbNativeMachineCostModel(prior);
		LmdbNativeCostVector open = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.OPEN, 1);
		for (int i = 0; i < 128; i++) {
			assertTrue(model.update(open, 1_000.0).accepted());
		}

		double learned = model.snapshot().coefficient(LmdbNativeCostVector.Feature.OPEN);
		assertTrue(learned >= 0.0);
		assertTrue(Math.abs(learned - 1_000.0) < Math.abs(10_000.0 - 1_000.0));
		for (LmdbNativeCostVector.Feature feature : LmdbNativeCostVector.Feature.values()) {
			assertTrue(model.snapshot().coefficient(feature) >= 0.0);
		}
	}

