	@Test
	void huberClippingPreventsOneOutlierFromReplacingTheModel() {
		LmdbNativeMachineCostModel model = new LmdbNativeMachineCostModel();
		LmdbNativeCostVector rows = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.GENERATED_ROW, 1_000);
		for (int i = 0; i < 64; i++) {
			model.update(rows, 20_000.0);
		}
		double before = model.snapshot().coefficient(LmdbNativeCostVector.Feature.GENERATED_ROW);
		LmdbNativeMachineCostModel.Update update = model.update(rows, 10_000_000_000.0);
		double after = model.snapshot().coefficient(LmdbNativeCostVector.Feature.GENERATED_ROW);

		assertTrue(update.clipped());
		assertTrue(after >= 0.0);
		assertTrue(after < before + 1_000_000.0);
	}

